extern "C" {

// P5:设备空闲显存查询(DFlash 低内存自适应跳过的探针;当前设备已由 runner 设定)。
// 返回 0 = ok;1 = setDevice 失败;2 = cudaMemGetInfo 失败。
int marlin_mem_get_info_ffi(size_t* free_b, size_t* total_b, int dev) {
    if (cudaSetDevice(dev) != cudaSuccess) return 1;
    return cudaMemGetInfo(free_b, total_b) == cudaSuccess ? 0 : 2;
}

// S2.4a(roadmap):设备默认内存池 trim 变现。模型/草稿载入后,临时加载缓冲
// 已 free 但仍被 stream-ordered 默认池缓存,空闲显存探测看不到(S1.6 G3 实测
// ~2.58G 被 allocator 吸收)。trim 后缓存块归还驱动,free_mem_bytes 才是
// 真实可用量。只释放未在用的缓存块,不动存活分配(graph 专属池不受影响)。
// 返回 0 = ok;1 = setDevice 失败;2 = 取默认池失败;3 = trim 失败;4 = trim 后查询失败。
int marlin_mem_pool_trim_ffi(int dev, size_t* free_after, size_t* total_after) {
    if (cudaSetDevice(dev) != cudaSuccess) return 1;
    cudaMemPool_t pool = nullptr;
    if (cudaDeviceGetDefaultMemPool(&pool, dev) != cudaSuccess) return 2;
    if (cudaMemPoolTrimTo(pool, 0) != cudaSuccess) return 3;
    if (cudaMemGetInfo(free_after, total_after) != cudaSuccess) return 4;
    return 0;
}

// 泄露排查定谳(2026-09-21):默认池 release_threshold 默认 UINT64_MAX(永不
// 自动归还),请求热路径的瞬态页全部滞留池缓存 → nvidia-smi used 拉满、真 free
// 归零 → 下一请求的图池提交/跨池分配 OOM 或直接踩坏状态(Xid 31 / libcuda
// segfault)。置 0 = 空闲页即刻归还,free 对所有分配方可见。
// 返回 0 = ok;1 = setDevice 失败;2 = 取默认池失败;3 = setAttribute 失败。
int marlin_mem_pool_release_threshold_ffi(int dev, size_t threshold_bytes) {
    if (cudaSetDevice(dev) != cudaSuccess) return 1;
    cudaMemPool_t pool = nullptr;
    if (cudaDeviceGetDefaultMemPool(&pool, dev) != cudaSuccess) return 2;
    if (cudaMemPoolSetAttribute(pool, cudaMemPoolAttrReleaseThreshold, &threshold_bytes) != cudaSuccess)
        return 3;
    return 0;
}

// vLLM 增强 kernel(f16 A / u4 B / f16 C / f16 scales)。
// workspace:零初始化 i32,>= (prob_n/64) * 128(覆盖 max_par=128 上限)。
// 错误码:0 ok;3 无配置;4 形状非法;5 设备不支持;另见 cudaGetErrorString。
int marlin_gemm_v2_ffi(const void* A, const void* B, void* C, void* c_tmp,
                       const void* b_scales, int prob_m, int prob_n,
                       int prob_k, void* workspace, int group_size, int dev,
                       uintptr_t stream) {
  int sms = 0;
  cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
  int num_groups = (group_size == -1) ? 1 : prob_k / group_size;
  return marlin_mm(A, B, C, c_tmp, const_cast<void*>(b_scales),
                   /*a_s=*/nullptr, /*a_is_s8=*/false, /*b_z=*/nullptr,
                   /*use_zp=*/false, prob_m, prob_n, prob_k, prob_k,
                   workspace, num_groups, group_size, dev,
                   (cudaStream_t)stream, -1, -1, sms, /*is_bf16=*/false);
}

// W4A8 变体:A = int8(已量化),a_scales = fp32 [M,1](per-token)。
// 其余契约与 marlin_gemm_v2_ffi 完全一致(B/scales/workspace 不变)。
int marlin_gemm_v2_w4a8_ffi(const void* A, const void* B, void* C,
                            void* c_tmp, const void* b_scales,
                            const void* a_scales, int prob_m, int prob_n,
                            int prob_k, void* workspace, int group_size,
                            int dev, uintptr_t stream, int is_bf16) {
  int sms = 0;
  cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
  int num_groups = (group_size == -1) ? 1 : prob_k / group_size;
  return marlin_mm(A, B, C, c_tmp, const_cast<void*>(b_scales),
                   const_cast<void*>(a_scales), /*a_is_s8=*/true,
                   /*b_z=*/nullptr, /*use_zp=*/false,
                   prob_m, prob_n, prob_k, prob_k, workspace, num_groups,
                   group_size, dev, (cudaStream_t)stream, -1, -1, sms,
                   /*is_bf16=*/is_bf16 != 0);
}

// P5-Q1a:AWQ(kU4 非对称)通路。b_zeros = marlin_zero_points 布局
// ((k/g, n/8) i32,LSB-first nibble 沿 n,scale_perm + n-interleave 已烘焙)。
int marlin_gemm_v2_awq_ffi(const void* A, const void* B, void* C,
                           void* c_tmp, const void* b_scales,
                           const void* b_zeros, int prob_m, int prob_n,
                           int prob_k, void* workspace, int group_size,
                           int dev, uintptr_t stream) {
  int sms = 0;
  cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
  int num_groups = (group_size == -1) ? 1 : prob_k / group_size;
  return marlin_mm(A, B, C, c_tmp, const_cast<void*>(b_scales),
                   /*a_s=*/nullptr, /*a_is_s8=*/false,
                   const_cast<void*>(b_zeros), /*use_zp=*/true,
                   prob_m, prob_n, prob_k, prob_k, workspace, num_groups,
                   group_size, dev, (cudaStream_t)stream, -1, -1, sms,
                   /*is_bf16=*/false);
}

}  // extern "C"
